mapper.select:
SELECT
    ,
    (SELECT COUNT(*)
       FROM user_notification_receiver r
      WHERE r.notification_id = n.id
        AND r.deleted_flag = 0) AS receiver_count
FROM user_notification n
WHERE 1 = 1

    AND n.type = #{type}


    AND n.create_by = #{createdBy}


    AND n.create_time >= #{beginTime}


    AND n.create_time <= #{endTime}


    ORDER BY ${orderByColumn} ${isAsc}

SELECT COUNT(*) FROM (
SELECT #{userId} AS user_id
) want LEFT JOIN sys_user u ON u.user_id = want.user_id WHERE u.user_id IS NULL OR u.del_flag <> '0' OR u.user_type NOT IN ('01', '02', '03')
